// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.connectivity.sosimport android.content.Contextimport androidx.work.CoroutineWorkerimport androidx.work.WorkerParametersimport timber.log.Timber/** * NOUS — SOS Location Update Worker (Module 11 v3 — P1). * * Strategy §"EmergencySOSEngine": "Location update: schedule WorkManager * periodic 60s (not 30s) — fix interval". * * This Worker is scheduled with a 60-second periodic interval after an * SOS is dispatched. It queries the current location and pushes a fresh * Google Maps link to all emergency contacts via SMS. * * ## Why 60s? * *  - WorkManager's minimum periodic interval is 15 minutes for standard *    periodic work; for shorter intervals we use a chained series of *    OneTimeWorkRequests with a 60s delay between each. *  - The original code used 30s — the strategy spec calls for 60s to *    reduce battery drain + SMS spam to emergency contacts. * * ## Inputs * *  - `emergencyContacts` — comma-separated phone numbers. *  - `locationDurationMinutes` — total duration (default 10 → 10 updates). * * ## Cancellation * * The worker is tagged with `SOS_LOCATION_WORK_TAG` so the engine can * cancel it via `WorkManager.cancelAllWorkByTag(...)` when the user cancels * the SOS or after the duration expires. */class SosLocationUpdateWorker(    appContext: Context,    params: WorkerParameters,) : CoroutineWorker(appContext, params) {    override suspend fun doWork(): Result {        val contactsStr = inputData.getString(KEY_EMERGENCY_CONTACTS) ?: return Result.failure()        val contacts = contactsStr.split(",").filter { it.isNotBlank() }        if (contacts.isEmpty()) return Result.success()        val updateIndex = inputData.getInt(KEY_UPDATE_INDEX, 0)        val totalUpdates = inputData.getInt(KEY_TOTAL_UPDATES, 10)        // Resolve the location provider — injected via Hilt at app level,        // but Workers can't use constructor injection directly. We use a        // static accessor (set by ConnectivityModule.provideLocationProvider).        val provider = SosLocationWorkerBridge.locationProvider        if (provider == null) {            Timber.tag(TAG).w("LocationProvider not available — skipping update $updateIndex/$totalUpdates.")            return Result.retry()        }        val location = try {            provider.getCurrentLocation()        } catch (t: Throwable) {            Timber.tag(TAG).e(t, "getCurrentLocation failed")            null        }        if (location == null) {            Timber.tag(TAG).w("No location fix for update $updateIndex — skipping SMS.")            return Result.success()        }        val link = location.toMapsLink()        val message = "SOS location update ($updateIndex/$totalUpdates): $link"        // Send the SMS via the bridge (avoids circular dep with SmsService).        for (contact in contacts) {            try {                SosLocationWorkerBridge.sendSms?.invoke(contact, message)                Timber.tag(TAG).i("Location update $updateIndex sent to $contact")            } catch (t: Throwable) {                Timber.tag(TAG).e(t, "Failed to send location update to $contact")            }        }        return Result.success()    }    companion object {        private const val TAG = "SosLocWorker"        const val KEY_EMERGENCY_CONTACTS = "emergency_contacts"        const val KEY_UPDATE_INDEX = "update_index"        const val KEY_TOTAL_UPDATES = "total_updates"        const val WORK_TAG = "nous_sos_location_work"    }}/** * Static bridge for the Worker to access Hilt-provided singletons. * * WorkManager instantiates Workers via reflection (no constructor injection), * so they can't directly access Hilt-provided `LocationProvider` / `SmsService`. * [com.roshan.persona.connectivity.di.ConnectivityModule] sets these static * references at app startup. * * This is a standard WorkManager pattern (also used by ReminderEngine in * Module 14). */object SosLocationWorkerBridge {    @Volatile    var locationProvider: LocationProvider? = null    @Volatile    var sendSms: ((String, String) -> Unit)? = null}